export async function processEventPlanSyncs(pool,bot){await ensureEventDraftTable(pool);await ensurePlanAvailabilityDraftTable(pool);await pool.query(`update portal_event_plans set status='expired',sync_requested_at=now(),updated_at=now() where status='collecting' and possible_end_date<current_date`);const plans=(await pool.query(`select id::int,discord_channel_id,discord_message_id from portal_event_plans where discord_channel_id is not null and discord_message_id is not null and sync_requested_at is not null and (synced_at is null or sync_requested_at>synced_at) order by sync_requested_at limit 25`)).rows;for(const plan of plans){try{const channel=await bot.channels.fetch(plan.discord_channel_id).catch(()=>null);if(!channel?.isTextBased())continue;const message=await channel.messages.fetch(plan.discord_message_id).catch(()=>null);if(!message)continue;const payload=await buildEventPlanDiscordPayload(pool,plan.id);await message.edit(preserveEventPlanImage(message,payload));await pool.query(`update portal_event_plans set synced_at=now() where id=$1`,[plan.id]);}catch(error){console.error(`[cotf-bot] Could not synchronize planning request ${plan.id}:`,error);}}}

